const sourceVersion = (sourceId: string) => {
  const source = expandedLegalSources.find((item) => item.id === sourceId);
  return source?.effectiveDate ? `시행 ${source.effectiveDate}` : `현행본 검토 ${REVIEW_DATE}`;
};

