function officialBranchPeriods(
  procedureId: string,
  citationId: string,
  branches: readonly { id: string; label: string; days: number; note: string }[],
): NonNullable<DurationEstimate["referencePeriods"]> {
  return branches.map((branch) => ({
    id: `ref-${procedureId}-${branch.id}`,
    kind: "NATIONWIDE_OFFICIAL_STANDARD" as const,
    label: branch.label,
    range: {
      min: branch.days,
      base: branch.days,
      max: branch.days,
      unit: "BUSINESS_DAY" as const,
    },
    jurisdiction: null,
    startsWhen: "해당 공식 처리분기의 완비된 신청을 접수한 날",
    includes: ["AUTHORITY_PROCESSING", "RESULT_NOTICE"] as const,
    citationIds: [citationId],
    sampleSize: null,
    observedFrom: null,
    observedTo: null,
    note: branch.note,
  }));
}

