const durationReferenceCitationIdsByProcedure = Object.fromEntries(
  Object.entries(durationReferencePeriodsByProcedure).map(([procedureId, periods]) => [
    procedureId,
    [...new Set((periods ?? []).flatMap((period) => period.citationIds))],
  ]),
) as Record<string, string[]>;

export const expandedProcedures: Procedure[] = permitSeeds.map((seed) => ({
  id: seed.id,
  name: seed.name,
  aliases: seed.aliases ?? [],
  description: seed.description,
  outcome: seed.outcome,
  stage: seed.stage,
  actionType: seed.actionType ?? "PERMIT",
  domain: seed.domain,
  lane: seed.lane,
  applicant: seed.applicant,
  receivingAuthority: seed.authority,
  statutoryDecisionMaker: seed.decisionMaker ?? seed.authority,
  consultationAuthorities: seed.consultations ?? [],
  submissions: seed.submissions,
  validity: "처분 내용·허가조건과 관계 법령에 따름",
  followUpObligations: seed.followUp,
  ruleIds: [`rule-exp-${seed.id}`, ...(additionalRuleIdsByProcedure[seed.id] ?? [])],
  citationIds: [
    `cit-exp-${seed.id}`,
    ...(seed.id === "hazard-prevention-plan"
      ? ["cit-osh-42-3-psm-deeming"]
      : []),
    ...(seed.durationSourceId ? [`cit-exp-${seed.id}-duration`] : []),
    ...(durationOverrideByProcedure.has(seed.id)
      ? [`cit-exp-${seed.id}-official-duration`]
      : []),
    ...(durationReferenceCitationIdsByProcedure[seed.id] ?? []),
  ],
  durationId: `duration-exp-${seed.id}`,
  verificationStatus: internallyReviewedExpandedProcedureIds.has(seed.id)
    ? "INTERNAL_REVIEWED"
    : seed.verified ? "AI_ASSISTED_DRAFT" : "TODO_LEGAL_REVIEW",
  reviewedAt: REVIEW_DATE,
  reviewNote: seed.reviewNote,
  deemedByProcedureIds: seed.deemedBy ?? [],
  deemedProcedureIds: seed.deems ?? [],
}));

export const expandedDurations: DurationEstimate[] = permitSeeds.map((seed) => {
  const override = durationOverrideByProcedure.get(seed.id);
  const referencePeriods = durationReferencePeriodsByProcedure[seed.id];
  const authorityProcessing = override
    ? override.range
      ? {
          min: override.range[0],
          base: override.range[1],
          max: override.range[2],
          unit: override.unit,
        }
      : null
    : seed.days
      ? { min: seed.days[0], base: seed.days[1], max: seed.days[2], unit: seed.durationUnit ?? "BUSINESS_DAY" }
      : null;
  const elapsed = override?.endToEndKnown === false ? null : authorityProcessing;
  return {
    id: `duration-exp-${seed.id}`,
    procedureId: seed.id,
    applicantPreparation: null,
    authorityProcessing,
    interagencyConsultation: null,
    elapsed,
    statutoryPeriod: override?.statutoryPeriod ?? seed.statutoryPeriod ?? null,
    stopClockRules: override?.stopClockRules ?? ["보완요구·현장보정·민원처리법상 처리기간 정지는 별도 확인"],
    variabilityFactors: seed.variability ?? ["대상 세부기준", "신청자료 완결성", "관계기관 협의"],
    evidenceType: override?.evidenceType ?? seed.durationEvidence ?? "INSUFFICIENT_DATA",
    citationIds: [...new Set([
      override
        ? `cit-exp-${seed.id}-official-duration`
        : seed.durationSourceId
          ? `cit-exp-${seed.id}-duration`
          : `cit-exp-${seed.id}`,
      ...(durationReferenceCitationIdsByProcedure[seed.id] ?? []),
    ])],
    sampleSize: null,
    assumptions: override?.assumptions ?? seed.durationAssumptions ?? [
      authorityProcessing
        ? "법령·공식 민원안내의 원 단위를 그대로 사용"
        : "전국 공통값이 확인되지 않은 절차는 임의 기간을 생성하지 않음",
    ],
    verifiedAt: REVIEW_DATE,
    legalConfidence: override ? "HIGH" : seed.verified ? "HIGH" : "MEDIUM",
    estimateConfidence: override
      ? (override.range === null || override.endToEndKnown === false || override.planningBasis === "OFFICIAL_CAP_ONLY" ? "LOW" : "HIGH")
      : seed.days
        ? (seed.verified ? "HIGH" : "MEDIUM")
        : referencePeriods?.some((period) => period.range !== null)
          ? "LOW"
          : "UNVERIFIED",
    planningBasis: override?.planningBasis ?? (override?.endToEndKnown === false
      ? "INSUFFICIENT_DATA"
      : authorityProcessing
        ? "DIRECT_OFFICIAL"
      : referencePeriods?.some((period) => period.kind === "LOCAL_OFFICIAL_STANDARD")
        ? "LOCAL_OFFICIAL_REFERENCE"
        : referencePeriods?.length
          ? "MILESTONE_ONLY"
          : "INSUFFICIENT_DATA"),
    ...(referencePeriods ? { referencePeriods } : {}),
  };
});

const edge = (
  id: string,
  from: string,
  to: string,
  conditionRuleId: string | null,
  note: string,
  strength: ProcedureEdge["strength"] = "LEGAL_HARD",
): ProcedureEdge => ({
  id,
  from,
  to,
  relation: "FINISH_TO_START",
  lag: 0,
  lagUnit: "BUSINESS_DAY",
  strength,
  conditionRuleId,
  citationIds: [],
  branchId: null,
  note,
});

const completionBranchEdges = (
  idPrefix: string,
  from: string,
  conditionRuleId: string,
  note: string,
): ProcedureEdge[] => [
  edge(`${idPrefix}-complex`, from, "factory-completion-report-complex", conditionRuleId, note, "PRACTICAL"),
  edge(`${idPrefix}-offsite`, from, "factory-completion-report-offsite", conditionRuleId, note, "PRACTICAL"),
];

const startEdge = (
  id: string,
  from: string,
  to: string,
  conditionRuleId: string,
  note: string,
): ProcedureEdge => ({
  ...edge(id, from, to, conditionRuleId, note, "PRACTICAL"),
  relation: "START_TO_START",
});

